#!/usr/bin/env node
/* biome-ignore-all lint/suspicious/noConsole: CLI entry point */
// This shim defers loading the real module until the compile cache is enabled.
// https://nodejs.org/api/module.html#moduleenablecompilecachecachedir
// enableCompileCache was added in Node.js 22.8.0, so we need to handle older versions.
const entryAt = performance.now();
try {
  const { enableCompileCache } = await import('node:module');
  if (enableCompileCache) {
    enableCompileCache();
  }
} catch {}

// Spawn the installed native binary for explicit opt-ins, macOS machines, or
// internal automatic enrollment. Explicit opt-outs always override defaults.
import { spawnSync } from 'node:child_process';
import { existsSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));

// Keep in sync with packages/vc-native/scripts/platforms.mjs.
const NATIVE_TARGETS = [
  'darwin-arm64',
  'darwin-x64',
  'linux-arm64',
  'linux-arm64-musl',
  'linux-x64',
  'linux-x64-musl',
  'win32-arm64',
  'win32-x64',
];

// musl's `ldd` names itself. npm and pnpm skip the other libc's package via
// its `libc` field, but Yarn classic installs both, so the launcher must pick
// one.
function isMusl() {
  const ldd = spawnSync('ldd', ['--version'], { encoding: 'utf8' });
  return `${ldd.stdout ?? ''}${ldd.stderr ?? ''}`.includes('musl');
}

function nativeTarget() {
  const target = `${process.platform}-${process.arch}`;
  return process.platform === 'linux' && isMusl() ? `${target}-musl` : target;
}

function resolveNative() {
  // Already running inside the native binary — never trampoline again.
  if (process.env.VERCEL_VC_NATIVE === '1') return null;
  const pkgName = `@vercel/vc-native-${nativeTarget()}`;
  const binName = process.platform === 'win32' ? 'vercel.exe' : 'vercel';
  // Walk up from this install's own tree looking for a sibling native
  // package. `require.resolve()` is not used because it falls back to
  // NODE_PATH and the global folders even when `paths` is given.
  let dir = __dirname;
  while (true) {
    const pkgDir = join(dir, 'node_modules', pkgName);
    if (existsSync(join(pkgDir, 'package.json'))) {
      const a = join(pkgDir, 'bin', binName);
      if (existsSync(a)) return a;
      const b = join(pkgDir, binName);
      if (existsSync(b)) return b;
    }
    const parent = dirname(dir);
    if (parent === dir) return null;
    dir = parent;
  }
}

function nativeUnavailableMessage() {
  const target = nativeTarget();
  if (NATIVE_TARGETS.includes(target)) {
    return (
      `The native Vercel CLI package @vercel/vc-native-${target} is not installed. ` +
      'Reinstall vercel without omitting optional dependencies (for example, npm i -g vercel@latest).'
    );
  }
  return (
    `Vercel CLI does not provide a native binary for ${target}. ` +
    `Supported platforms: ${NATIVE_TARGETS.join(', ')}.`
  );
}

// Read `--global-config`/`-Q` without loading the full CLI arg parser.
function globalConfigDirFromArgv() {
  const argv = process.argv.slice(2);
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '--global-config' || arg === '-Q') {
      return argv[i + 1];
    }
    if (arg.startsWith('--global-config=')) {
      return arg.slice('--global-config='.length);
    }
  }
  return undefined;
}

// Any failure to read config counts as "not opted in".
async function isNativeBinaryOptedIn() {
  const envOverride = process.env.VERCEL_CLI_USE_NATIVE_BINARY;
  if (envOverride === '1' || envOverride === 'true') return true;
  if (envOverride === '0' || envOverride === 'false') return false;

  try {
    // Zod-free subpath to avoid loading zod + schemas on this hot path.
    const config = await import('@vercel/cli-config/paths');
    const argDir = globalConfigDirFromArgv();
    const configDir = argDir
      ? resolve(process.cwd(), argDir)
      : config.getGlobalPathConfig();
    const configPath = config.getConfigFilePath(configDir);
    const preference = config.readGlobalConfigFlag(
      configPath,
      'useNativeBinary'
    );
    if (typeof preference === 'boolean') return preference;
    // All macOS machines are opted in unless they explicitly opt out above.
    if (process.platform === 'darwin') return true;
    return (
      config.readGlobalConfigFlag(configPath, 'nativeBinaryAutoOptIn') === true
    );
  } catch {
    return false;
  }
}

// Keep the opt-out escape hatch in Node even when the native binary cannot
// start. The full CLI parser still validates the command and its arguments.
const disableBinary = process.argv.slice(2).includes('--disable-binary');
const nativeBin = resolveNative();
const bin = disableBinary ? null : nativeBin;

// Internal worker arguments intentionally trampoline too. The packaged native
// binary sets VERCEL_VC_NATIVE=1 in pkg.js and re-enters this file, where
// resolveNative() returns null and the worker branch below handles the request.
if (bin && (await isNativeBinaryOptedIn())) {
  process.env.VERCEL_VC_NATIVE = '1';
  // Do not fall through to JS on spawn/loader failures — surface them so
  // native binary issues (e.g. glibc mismatch) are visible.
  const r = spawnSync(bin, process.argv.slice(2), {
    stdio: 'inherit',
    windowsHide: true,
    env: {
      ...process.env,
      // Upgrades belong to the vercel package, not its native runtime dependency.
      // Always replace an inherited value with this launcher's own entrypoint.
      VERCEL_CLI_PACKAGE_ENTRYPOINT: fileURLToPath(import.meta.url),
      VERCEL_CLI_PACKAGE_EXECUTABLE: bin,
    },
  });
  if (r.error) {
    console.error(r.error.message);
    process.exit(1);
  }
  if (r.signal) {
    try {
      process.kill(process.pid, r.signal);
    } catch {}
  }
  process.exit(r.status ?? 1);
}

if (process.argv[2] === '--internal-build-worker') {
  const {
    applyInternalBuildRequest,
    InternalBuildWorkerReport,
    preloadInternalBuild,
    waitForInternalBuildRequest,
  } = await import('./internal-build-worker.js');
  const report = new InternalBuildWorkerReport({ entryAt });
  // Only module loading belongs here: argv, env, and cwd still belong to the
  // prewarm process until the build request is applied.
  const handoff = await waitForInternalBuildRequest(
    process.argv.slice(2),
    () =>
      preloadInternalBuild(
        () => import('./commands/build/index.js'),
        () => import('./internal-build.js'),
        report
      ),
    { report }
  );
  globalThis[Symbol.for('vercel.cli.fatal-error-handler')] = error =>
    handoff.error(error);

  try {
    // The caller must provide the complete environment for a non-interactive
    // build-container invocation before normal CLI initialization starts.
    applyInternalBuildRequest(handoff.request);
    const { runInternalBuild } = await import('./internal-build.js');
    let exitCode = await runInternalBuild();
    if (exitCode === undefined) {
      // Importing index.js starts the full CLI with the applied request.
      const { cliPromise } = await import('./index.js');
      exitCode = await cliPromise;
    }
    await handoff.complete(exitCode ?? 0);
  } catch (error) {
    await handoff.error(error);
    process.exitCode = 1;
  }

  process.exit(process.exitCode ?? 0);
}

// Fast path for --version to avoid loading the entire CLI
if (
  process.argv.length === 3 &&
  (process.argv[2] === '--version' || process.argv[2] === '-v')
) {
  const { version, buildLabel } = await import('./version.mjs');
  const labels = [];
  if (process.env.VERCEL_VC_NATIVE === '1') labels.push('native');
  // Optional build metadata stamped by CI (e.g. "pr-115 abc1234").
  if (buildLabel) labels.push(buildLabel);
  const suffix = labels.length > 0 ? ` (${labels.join(', ')})` : '';
  console.error(`Vercel CLI ${version}${suffix}`);
  console.log(version);
  process.exit(0);
}

// Fast path for --help to avoid loading the entire CLI. The build generates
// root-help-commands.mjs from the command registry; without it, fall through
// to the full CLI, which renders the same help from the registry.
if (
  process.argv.length === 3 &&
  (process.argv[2] === '--help' || process.argv[2] === '-h')
) {
  let rootHelp;
  try {
    const { version } = await import('./version.mjs');
    const { help } = await import('./help.js');
    const { rootHelpCommands } = await import('./root-help-commands.mjs');
    rootHelp = {
      version,
      text: help(rootHelpCommands, process.stdout.columns),
    };
  } catch {
    rootHelp = undefined;
  }
  if (rootHelp) {
    console.error(`Vercel CLI ${rootHelp.version}`);
    process.stdout.write(rootHelp.text);
    process.exit(0);
  }
}

try {
  await import('./index.js');
} catch (error) {
  // Without a native binary the JS CLI is the only option; if its
  // dependencies are not installed either, name the missing native package.
  if (
    !nativeBin &&
    process.env.VERCEL_VC_NATIVE !== '1' &&
    error?.code === 'ERR_MODULE_NOT_FOUND'
  ) {
    console.error(`Error: ${nativeUnavailableMessage()}`);
    console.error(error.message);
    process.exit(1);
  }
  // Global-config paths are resolved during module initialization, before the
  // command router and its client exist. Report local parser failures without
  // dumping a stack or loading configuration again to construct the error.
  if (
    error?.name !== 'ArgError' ||
    ![
      'ARG_UNKNOWN_OPTION',
      'ARG_MISSING_REQUIRED_LONGARG',
      'ARG_MISSING_REQUIRED_SHORTARG',
    ].includes(error.code)
  ) {
    throw error;
  }
  let nonInteractive = false;
  for (const arg of process.argv.slice(2)) {
    if (arg === '--') break;
    if (arg === '--non-interactive' || arg === '--non-interactive=true') {
      nonInteractive = true;
    } else if (arg === '--non-interactive=false') {
      nonInteractive = false;
    }
  }
  if (nonInteractive) {
    console.log(
      JSON.stringify(
        {
          status: 'error',
          reason: 'invalid_arguments',
          message: error.message,
        },
        null,
        2
      )
    );
  } else {
    console.error(`✗ ${error.message}`);
  }
  // A usage error, like every other unknown or incomplete option.
  process.exit(2);
}
